const context = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Build Discovery Context', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Session → map id + test flag. Test sessions (Ryan's console / dashboard) write under Discovery/Test.\nconst inp = $input.first().json || {};\nconst sessionId = String(inp.sessionId || ('anon' + Date.now().toString(36)));\nconst short = sessionId.replace(/[^a-z0-9]/gi, '').toLowerCase().slice(0, 28) || 'anon';\nconst text = String(inp.chatInput || '').trim();\nconst testMode = /^(dash_|test_|mcp)/i.test(sessionId) || /^dash/i.test(short) || inp.test_mode === true;\nreturn [{ json: { session_id: sessionId, map_id: 'map_' + short, text, test_mode: testMode, tenant_id: 'fusiontech', started_at: new Date().toISOString() } }];\n" }, position: [220, 300] },
  output: [{ session_id: 'abc123', map_id: 'map_abc123', text: 'We are a logistics company', test_mode: false, tenant_id: 'fusiontech', started_at: '2026-01-01T00:00:00.000Z' }]
});

