const note = sticky("## CEO Brain — Discovery Console (Company Discovery & Onboarding Agent)\nHosted chat where a business owner talks to the discovery consultant. Every turn: load the Company Map so far (ceo_company_maps) → brain + discovery playbook live from the vault → Claude → validate, merge, guardrails, rules fallback → save map + agent run → write the Client Digital Company Map note into the vault (Discovery/; tests under Discovery/Test) → when complete: proposal DRAFT (no pricing) + review task + email Ryan → reply.\n\nSource of truth: ryan/ceo-brain/workflows/discovery-console/build.js. Do not hand-edit Code nodes.", [chat, context, loadMap, loadBrain, loadPlaybook], { color: 4 });

export default workflow('ceo-brain-discovery-console', 'CEO Brain — Discovery Console')
  .add(chat)
  .to(context)
  .to(loadMap)
  .to(loadBrain)
  .to(loadPlaybook)
  .to(compose)
  .to(claude.to(finalize))
  .add(claude.onError(finalize))
  .add(finalize)
  .to(saveMap)
  .to(logRun)
  .to(getNote)
  .to(noteExists
    .onTrue(editNote.to(isComplete))
    .onFalse(createNote.to(isComplete)))
  .add(isComplete
    .onTrue(proposalTask.to(emailOwner).to(reply))
    .onFalse(reply))
  .add(note);
